scwin.vScrenID = "ULDINS30600.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.stf.showObj(grd_DtlList01, false);
    $c.stf.showObj(grd_DtlList02, false);
    $c.stf.showObj(grd_DtlList03, false);
    $c.stf.showObj(grd_DtlList04, false);
    $c.stf.showObj(grd_DtlList05, false);
    $c.stf.showObj(grd_DtlList06, false);
    $c.stf.showObj(grd_DtlList07, false);
    $c.stf.showObj(grd_DtlList09, false);
    $c.stf.showObj(grd_DtlList10, false);
    $c.stf.showObj(grd_DtlList11, false);
    $c.stf.showObj(grd_DtlList12, false);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    ins_combo_set(dts_STD_CD_APPL_CONTN_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03425", "ALL"); //상품구분 		

};


/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_FROM_STD_CD_APPL_DD.setValue(sToday);
    edt_TO_STD_CD_APPL_DD.setValue(sToday);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pGubun) {
    if (pGubun == "ins_search") {
        dts_List.removeAll();
    }
    dts_DtlList01.removeAll();
    dts_DtlList02.removeAll();
    dts_DtlList03.removeAll();
    dts_DtlList04.removeAll();
    dts_DtlList05.removeAll();
    dts_DtlList06.removeAll();
    dts_DtlList07.removeAll();
    dts_DtlList09.removeAll();
    dts_DtlList10.removeAll();
    dts_DtlList11.removeAll();
    dts_DtlList12.removeAll();
    //txb_TotalCnt.value = "총 0건";

};



/**
 * 조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_search");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_search")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listautoEditHistListInquiry" + "&outputMessageId=INS_LIST_AUTO_EDIT_HIST_LIST_INQUIRY" + "&param01=" + $c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) + "&param02=" + $c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) + "&param03=" + $c.stf.getObjectValue(cmb_STD_CD_APPL_CONTN_TP_CD) + "&param04=" + $c.stf.getObjectValue(txb_ISU_NM);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 상세조회
 */
scwin.ins_DtlSearch = function(pGubun) {
    //데이터셋 초기화
    scwin.fn_InitDs("ins_DtlSearch");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_DtlSearch")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    if (pGubun == "01") {
        scwin.ins_DtlSearch01();
    } else if (pGubun == "02") {
        scwin.ins_DtlSearch02();
    } else if (pGubun == "03") {
        scwin.ins_DtlSearch03();
    } else if (pGubun == "04") {
        scwin.ins_DtlSearch04();
    } else if (pGubun == "05") {
        scwin.ins_DtlSearch05();
    } else if (pGubun == "06") {
        scwin.ins_DtlSearch06();
    } else if (pGubun == "07") {
        scwin.ins_DtlSearch07();
    } else if (pGubun == "09") {
        scwin.ins_DtlSearch09();
    } else if (pGubun == "10") {
        scwin.ins_DtlSearch10();
    } else if (pGubun == "11") {
        scwin.ins_DtlSearch11();
    } else if (pGubun == "12") {
        scwin.ins_DtlSearch12();
    } else if (pGubun == "13") {
        scwin.ins_DtlSearch13();
    }
};



